   736	void ShellController::open_printer_conversation(const std::string& printer_name, bool connect)
   737	{
   738	    if (m_task_open || m_printer_panel == nullptr || m_tabpanel == nullptr)
   739	        return;
   740	    // Every caller names a preset it has just read, so a miss means it went
   741	    // between the menu and the click: say so as Orca does, never open a
   742	    // conversation about another printer.
   743	    if (!printer_name.empty() && !preset_exists(Preset::TYPE_PRINTER, printer_name)) {
   744	        show_error(m_frame, wxString::Format(_L("The printer preset \"%s\" was not found."), from_u8(printer_name)));
   745	        return;
   746	    }
   747	    m_printer_panel->open(connect ? PrinterSetup::ConversationMode::Connect : printer_name.empty() ? PrinterSetup::ConversationMode::Add :
   748	                                                 PrinterSetup::ConversationMode::Change,
   749	                          printer_name);
   750	    show_task_panel();
   751	}
