   485	
   486	void ShellController::on_frame_destroy(wxWindowDestroyEvent& event)
   487	{
   488	    if (event.GetWindow() == m_frame) {
   489	        m_runtime_timer.Stop();
   490	        m_installed = false;
   491	        wxGetApp().show_config_wizard_on_startup = m_saved_show_config_wizard_on_startup;
   492	        m_prepare_canvas_presentation.abandon();
   493	        // This controller lives in a static slot and outlives every window,
   494	        // so whatever it owns that unbinds from the Plater has to go now,
   495	        // while the frame's children still exist: wx sends this event from
   496	        // the top-level window's destructor, before DestroyChildren. Left in
   497	        // place, the slot's destructor ran ~OrcaWorkspaceAdapter against a
   498	        // deleted Plater after main had returned -- an access violation at
   499	        // process exit in every run that did not detach the shell by hand.
   500	        // Same order as uninstall(): the pane and status row first, since
   501	        // their destructors talk to persistence and the workspace, then
   502	        // those two. The remaining children die with the frame.
   503	        if (m_left_pane != nullptr) {
   504	            m_left_pane->Destroy();
   505	            m_left_pane = nullptr;
   506	        }
   507	        if (m_agent_pane != nullptr) {
   508	            m_agent_pane->web_view().host().tools().set_version_callbacks({}, {});
   509	            m_agent_pane->Destroy();
   510	            m_agent_pane = nullptr;
   511	        }
   512	        // The printer panel holds a host of its own over the same workspace,
   513	        // so it goes with the pane rather than with Home's children later.
   514	        if (m_printer_panel != nullptr) {
   515	            m_printer_panel->Destroy();
   516	            m_printer_panel = nullptr;
   517	        }
   518	        if (m_status_row != nullptr) {
   519	            m_status_row->Destroy();
   520	            m_status_row = nullptr;
   521	        }
   522	        if (m_home != nullptr) {
   523	            m_home->set_live(false);
   524	            m_home->backend().set_autosave(nullptr);
   525	        }
   526	        m_plater->set_before_project_release({});
   527	        m_plater->set_external_project_open_handler({});
   528	        m_autosave.reset();
   529	        m_persistence.reset();
   530	        m_workspace.reset();
   531	    }
   532	    event.Skip();
   533	}
