   616	void ShellController::uninstall()
   617	{
   618	    m_runtime_timer.Stop();
   619	    if (!m_installed)
   620	        return;
   621	    m_installed = false;
   622	    m_agent_pane_collapsed = false;
   623	    m_frame->Unbind(wxEVT_DESTROY, &ShellController::on_frame_destroy, this);
   624	    m_frame->Unbind(wxEVT_SIZE, &ShellController::on_frame_size, this);
   625	    m_tabpanel->Unbind(wxEVT_NOTEBOOK_PAGE_CHANGED, &ShellController::on_notebook_page_changed, this);
   626	
   627	    m_prepare_canvas_presentation.detach();
   628	    m_plater->get_collapse_toolbar().set_enabled(m_saved_collapse_toolbar_enabled);
   629	    m_plater->set_sidebar_available(true);
   630	    m_plater->set_auto_preview_after_slice(m_saved_auto_preview_after_slice);
   631	    wxGetApp().show_config_wizard_on_startup = m_saved_show_config_wizard_on_startup;
   632	    // A printer connection may have installed a provider the slicing profile
   633	    // does not select; hand the choice back to Orca's profile-driven policy.
   634	    wxGetApp().switch_printer_agent();
   635	    m_tabpanel->GetBtnsListCtrl()->Show();
   636	
   637	    if (m_center_sizer != nullptr) {
   638	        if (m_workspace_sizer != nullptr) {
   639	            m_workspace_sizer->Detach(m_tabpanel);
   640	            if (m_home != nullptr)
   641	                m_workspace_sizer->Detach(m_home);
   642	        }
   643	        if (m_left_pane != nullptr)
   644	            m_center_sizer->Detach(m_left_pane);
   645	        if (m_agent_resize_handle != nullptr)
   646	            m_center_sizer->Detach(m_agent_resize_handle);
   647	        if (m_agent_pane != nullptr)
   648	            m_center_sizer->Detach(m_agent_pane);
   649	        if (m_printer_panel != nullptr)
   650	            m_center_sizer->Detach(m_printer_panel);
   651	        m_main_sizer->Detach(m_center_sizer);
   652	        delete m_center_sizer;
   653	        m_center_sizer = nullptr;
   654	        m_workspace_sizer = nullptr;
   655	    }
   656	    if (m_status_row != nullptr)
   657	        m_main_sizer->Detach(m_status_row);
   658	    if (m_main_sizer->GetItem(m_tabpanel) == nullptr)
   659	        m_main_sizer->Add(m_tabpanel, 1, wxEXPAND | wxTOP, 0);
   660	
   661	    if (m_left_pane != nullptr) {
   662	        m_left_pane->Destroy();
   663	        m_left_pane = nullptr;
   664	    }
   665	    if (m_status_row != nullptr) {
   666	        m_status_row->Destroy();
   667	        m_status_row = nullptr;
   668	    }
   669	    if (m_agent_resize_handle != nullptr) {
   670	        m_agent_resize_handle->Destroy();
   671	        m_agent_resize_handle = nullptr;
   672	    }
   673	    if (m_agent_pane != nullptr) {
   674	        m_agent_pane->web_view().host().tools().set_version_callbacks({}, {});
   675	        m_agent_pane->Destroy();
   676	        m_agent_pane = nullptr;
   677	    }
   678	    if (m_printer_panel != nullptr) {
   679	        m_printer_panel->Destroy();
   680	        m_printer_panel = nullptr;
   681	    }
   682	    if (m_home != nullptr) {
   683	        m_home->Destroy();
   684	        m_home = nullptr;
   685	    }
   686	    // The Notebook is hidden only while Home is up, so the stock presentation
   687	    // gets it back shown.
   688	    m_tabpanel->Show();
   689	    // After the pane (and with it the Agent host) is gone.
   690	    m_plater->set_before_project_release({});
   691	    m_plater->set_external_project_open_handler({});
   692	    m_autosave.reset();
   693	    if (m_plater->get_project_name().empty())
   694	        m_frame->SetTitle(m_saved_frame_title);
   695	    else
   696	        m_plater->update_title_dirty_status();
   697	    Slic3r::set_backup_suspended(false);
   698	    m_persistence.reset();
   699	    m_workspace.reset();
