   796	void ShellController::on_page_changed()
   797	{
   798	    if (!m_installed || m_home == nullptr || m_tabpanel == nullptr)
   799	        return;
   800	    if (m_task_open) {
   801	        if (m_tabpanel->GetSelection() != m_task_origin_tab)
   802	            m_printer_panel->close();
   803	        return;
   804	    }
   805	    const bool home = m_tabpanel->GetSelection() == MainFrame::tpHome;
   806	    if (home)
   807	        m_home->refresh();
   808	    m_home->set_live(home);
   809	    // A throwaway setup webview elsewhere (the Add a printer dialog) may have
   810	    // written a working agent config since the docked pane last checked; push
   811	    // it in now, the same "refresh on the way in" pattern as Home's gallery
   812	    // above, rather than reloading the page or polling continuously.
   813	    if (m_agent_config_possibly_changed) {
   814	        m_agent_config_possibly_changed = false;
   815	        Agent::AgentRuntime runtime = Agent::load_agent_runtime(wxGetApp().app_config);
   816	        m_agent_pane->web_view().host().set_agent(std::move(runtime.service), runtime.availability);
   817	    }
   818	    // Home and the Notebook share the workspace slot, so exactly one is shown.
   819	    // The Notebook is only hidden while Home is the selection: post_init
   820	    // selects the Prepare tab to map the GL canvas before it initialises
   821	    // OpenGL, and this handler runs on that selection, so the Notebook is
   822	    // shown at the moment the canvas has to be on screen.
   823	    // The header belongs to the workspace: its controls act on the open
   824	    // project, so Home, which has no project in front, shows no header.
   825	    m_home->Show(home);
   826	    m_tabpanel->Show(!home);
   827	    m_status_row->Show(!home);
   828	    // The pane lists the project being prepared; Preview draws its own plate
   829	    // picker and Home has no project in front.
   830	    m_left_pane->Show(!home && m_tabpanel->GetSelection() == MainFrame::tp3DEditor);
   831	    m_frame->Layout();
   832	    set_agent_pane_collapsed(home ? true : m_agent_pane_user_collapsed);
   833	}
