   541	
   542	int ShellController::agent_pane_width_within(int width) const
   543	{
   544	    if (m_theme == nullptr || m_frame == nullptr)
   545	        return width;
   546	    const AgentPaneMetrics& metrics = m_theme->metrics().agent_pane;
   547	    const int min_width = m_frame->FromDIP(metrics.min_width);
   548	    const int workspace_min_width = m_frame->FromDIP(metrics.workspace_min_width);
   549	    const int handle_width = m_frame->FromDIP(metrics.resize_handle_width);
   550	    // The Plates / Project pane is also beside the canvas, so the Agent pane
   551	    // may not take what the canvas needs while it is on screen.
   552	    const int left_width = m_left_pane != nullptr && m_left_pane->IsShown() ? m_left_pane->GetSize().x : 0;
   553	    const int max_width = std::max(min_width, m_frame->GetClientSize().x - workspace_min_width - handle_width - left_width);
   554	    return std::clamp(width, min_width, max_width);
   555	}
   556	
   557	void ShellController::request_agent_pane_width(int width)
   558	{
   559	    // Remember what the pane can actually take, not what the pointer asked
   560	    // for. A drag that runs past the edge of a small window would otherwise
   561	    // record a width the pane never had, and the pane would claim it -- at the
   562	    // workspace's expense -- the next time the window grew enough to allow it.
   563	    // A width the window merely cannot afford right now is a different case:
   564	    // apply_agent_pane_width() narrows the pane without touching the
   565	    // preference, so growing the window restores the width the person chose.
   566	    m_agent_pane_preferred_width = agent_pane_width_within(width);
   567	    apply_agent_pane_width();
   568	}
   569	
   570	void ShellController::apply_agent_pane_width()
   571	{
   572	    if (m_theme == nullptr || m_frame == nullptr || m_center_sizer == nullptr || m_agent_pane == nullptr)
   573	        return;
   574	    if (m_agent_pane_collapsed)
   575	        return;
   576	    const int width = agent_pane_width_within(m_agent_pane_preferred_width);
   577	    m_center_sizer->SetItemMinSize(m_agent_pane, width, -1);
   578	    // Lay out from the frame, not from m_center_sizer. A sizer lays itself out
   579	    // against the dimension it was last given, which during a frame resize is
   580	    // still the previous client width; the frame reads the current one from the
   581	    // window. Laying out the sizer directly leaves the workspace and the
   582	    // divider sized for the old width while the pane takes the new one, so they
   583	    // overlap, and the next resize swaps which of them is stale.
   584	    m_frame->Layout();
   585	}
   586	
   587	void ShellController::set_agent_pane_collapsed(bool collapsed)
   588	{
   589	    if (m_agent_pane == nullptr || m_agent_resize_handle == nullptr || m_agent_pane_collapsed == collapsed)
   590	        return;
   591	    m_agent_pane_collapsed = collapsed;
   592	    // Hidden, never destroyed: the conversation, the loaded page, and the MCP
   593	    // runtime all outlive a collapse. A hidden sizer item takes no space, so
   594	    // the workspace grows into the whole width with no second width policy.
   595	    m_agent_pane->Show(!collapsed);
   596	    m_agent_resize_handle->Show(!collapsed);
   597	    if (m_status_row != nullptr)
   598	        m_status_row->set_agent_pane_collapsed(collapsed);
   599	    // Expanding re-applies the width policy, which lays out on its way; a
   600	    // collapsed pane has no width to apply, so it lays out here.
   601	    if (collapsed)
   602	        m_frame->Layout();
   603	    else
   604	        apply_agent_pane_width();
   605	}
