  38	            (std::filesystem::u8path(discovery_path).parent_path() / "printer_facts.json").u8string());
  39	    } catch (const boost::system::system_error& error) {
  40	        startup_error = error.what();
  41	    } catch (const std::filesystem::filesystem_error& error) {
  42	        startup_error = error.what();
  43	    } catch (const std::ios_base::failure& error) {
  44	        startup_error = "Could not write MCP discovery at " + discovery_path + ": " + error.what();
  45	    }
  46	#ifdef _WIN32
  47	    const std::string helper_name = "jusprin-mcp.exe";
  48	#else
  49	    const std::string helper_name = "jusprin-mcp";
  50	#endif
  51	    const auto executable = std::filesystem::u8path(wxStandardPaths::Get().GetExecutablePath().ToUTF8().data());
  52	    const auto helper = executable.parent_path() / helper_name;
  53	    auto launcher = helper;
  54	    std::vector<std::string> launch_arguments;
  55	#if defined(__linux__)
  56	    wxString appimage;
  57	    if (wxGetEnv("APPIMAGE", &appimage) && !appimage.empty()) {
  58	        launcher = std::filesystem::u8path(appimage.ToUTF8().data());
