 658	{
 659	    if (event.ShiftDown() && event.GetKeyCode() == WXK_F10 &&
 660	        m_navigation.tab() == PaneTab::Plates && m_focus_row >= 0 && m_focus_row < int(m_rows.size())) {
 661	        open_row_menu(m_rows[m_focus_row]);
 662	        return;
 663	    }
 664	    if (event.ControlDown() && event.GetKeyCode() == WXK_TAB) {
 665	        if (m_navigation.tab() == PaneTab::Plates)
 666	            show_project();
 667	        else
 668	            show_plates();
 669	        m_tab_focus_visible = true;
 670	        SetName(m_navigation.tab() == PaneTab::Plates ? _L("Plates tab") : _L("Project tab"));
 671	        Refresh();
 672	        return;
 673	    }
 674	    if (event.GetKeyCode() == WXK_ESCAPE && handle_escape())
 675	        return;
 676	    if (!handle_key(event.GetKeyCode()))
 677	        event.Skip();
 678	}
