4266	
4267	    // Home shows no header and always collapses the Agent pane; leaving Home
4268	    // shows the header and restores what the person last chose for the pane
4269	    // on Prepare, in both directions. Ends back on Home, where every mode
4270	    // started before this check existed.
4271	    void verify_agent_pane_follows_page(std::function<void()> next)
4272	    {
4273	        ShellController* shell = installed_shell();
4274	        auto collapsed = [shell] { return shell->is_agent_pane_collapsed() && !shell->agent_pane()->IsShown(); };
4275	        auto expanded  = [shell] { return !shell->is_agent_pane_collapsed() && shell->agent_pane()->IsShown(); };
4276	        auto steps = std::make_shared<std::vector<PaneStep>>(std::vector<PaneStep>{
4277	            {MainFrame::tp3DEditor, "agent_pane_prepare_first_visit", [this, shell, collapsed, expanded] {
4278	                 check(shell->status_row()->IsShown(), "status_row_shown_on_prepare");
4279	                 verify_header_layout();
4280	                 check(expanded(), "agent_pane_shown_on_prepare");
4281	                 shell->toggle_agent_pane();
4282	                 check(collapsed(), "agent_pane_user_collapses_on_prepare");
4283	             }},
4284	            {MainFrame::tpHome, "agent_pane_home_after_user_collapse", [this, shell, collapsed] {
4285	                 check(!shell->status_row()->IsShown(), "status_row_hidden_on_return_to_home");
4286	                 check(collapsed(), "agent_pane_collapsed_on_home_after_user_collapse");
4287	             }},
4288	            {MainFrame::tp3DEditor, "agent_pane_prepare_after_user_collapse", [this, shell, collapsed, expanded] {
4289	                 check(collapsed(), "agent_pane_user_collapse_restored_on_prepare");
4290	                 shell->toggle_agent_pane();
4291	                 check(expanded(), "agent_pane_user_expands_on_prepare");
4292	             }},
4293	            {MainFrame::tpHome, "agent_pane_home_after_user_expand",
4294	             [this, collapsed] { check(collapsed(), "agent_pane_collapsed_on_home_after_user_expand"); }},
4295	            {MainFrame::tp3DEditor, "agent_pane_prepare_after_user_expand",
4296	             [this, expanded] { check(expanded(), "agent_pane_user_expand_restored_on_prepare"); }},
4297	            {MainFrame::tpHome, "agent_pane_returns_home", [] {}},
4298	        });
4299	        run_pane_steps(steps, 0, std::move(next));
4300	    }
