4302	    void run_pane_steps(std::shared_ptr<std::vector<PaneStep>> steps, size_t index, std::function<void()> next)
4303	    {
4304	        if (index == steps->size()) {
4305	            next();
4306	            return;
4307	        }
4308	        const PaneStep& step = (*steps)[index];
4309	        // The header's Home button goes to Home; Home's own page returns to
4310	        // Prepare through the same request its backend makes.
4311	        StatusRow* row = installed_shell()->status_row();
4312	        if (step.tab == MainFrame::tpHome)
4313	            row->request_home();
4314	        else
4315	            row->request_prepare();
4316	        const int tab = step.tab;
4317	        wait_until([this, tab] { return m_notebook->GetSelection() == tab; }, step.name,
4318	                   [self = shared_from_this(), steps, index, next] {
4319	                       (*steps)[index].on_arrival();
4320	                       self->run_pane_steps(steps, index + 1, next);
4321	                   });
4322	    }
