8783	    // Each one on its own can look right while the three together do not: a
8784	    // layout run against a stale width sizes some of them for the previous
8785	    // width, so they overlap and the pane covers part of the workspace.
8786	    void verify_agent_pane_tiling(const std::string& name)
8787	    {
8788	        auto* pane = installed_shell()->agent_pane();
8789	        auto* divider = wxWindow::FindWindowByName("Resize Agent panel", m_frame);
8790	        if (pane == nullptr || divider == nullptr || installed_shell()->is_agent_pane_collapsed())
8791	            return;
8792	        const int client = m_frame->GetClientSize().x;
8793	        const wxRect workspace = m_notebook->GetRect();
8794	        const wxRect bar = divider->GetRect();
8795	        const wxRect agent = pane->GetRect();
8796	        // The Plates / Project pane, when shown, is the first column.
8797	        const LeftPane* left_pane = installed_shell()->left_pane();
8798	        const bool left_shown = left_pane != nullptr && left_pane->IsShown();
8799	        const int  origin = left_shown ? left_pane->GetRect().GetRight() + 1 : 0;
8800	        const bool tiled = (!left_shown || left_pane->GetRect().x == 0) && workspace.x == origin && workspace.GetWidth() > 0 &&
8801	                           workspace.GetRight() + 1 == bar.x &&
8802	                           bar.GetRight() + 1 == agent.x &&
8803	                           agent.GetRight() + 1 == client;
8804	        check(tiled, "agent_panel_columns_tile_the_client_" + name);
8805	        if (!tiled)
8806	            std::cerr << "HARNESS DETAIL client=" << client << " workspace=" << workspace.x << "+"
8807	                      << workspace.GetWidth() << " divider=" << bar.x << "+" << bar.GetWidth()
8808	                      << " pane=" << agent.x << "+" << agent.GetWidth() << '\n';
