 765	void LeftPane::draw(wxGraphicsContext& gc, const wxSize& client)
 766	{
 767	    const ShellPalette&    p    = m_theme.palette(m_dark);
 768	    const LeftPaneMetrics& pane = m_theme.metrics().left_pane;
 769	
 770	    gc.SetPen(*wxTRANSPARENT_PEN);
 771	    gc.SetBrush(wxBrush(p.surface_subtle));
 772	    gc.DrawRectangle(0, 0, client.x, client.y);
 773	    // The pane's right edge.
 774	    gc.SetPen(wxPen(p.border_subtle, 1));
 775	    gc.StrokeLine(client.x - 0.5, 0, client.x - 0.5, client.y);
 776	
 777	    m_hits.clear();
 778	    draw_tabs(gc, client.x - 1);
 779	
 780	    const int top = FromDIP(pane.padding_y + pane.tab_height);
 781	    gc.PushState();
 782	    gc.Clip(0, top, client.x - 1, std::max(0, client.y - top));
 783	    m_content_height = (m_navigation.tab() == PaneTab::Plates ? draw_plates(gc, top - m_scroll, client.x - 1)
 784	                                                              : draw_project(gc, top - m_scroll, client.x - 1)) + m_scroll - top;
 785	    gc.PopState();
 786	    clamp_scroll();
 787	
 788	    if (m_navigation.tab() == PaneTab::Project && m_focus_visible && HasFocus()) {
 789	        const std::vector<std::size_t> actions = action_hits();
 790	        if (m_action_focus >= 0 && m_action_focus < int(actions.size())) {
 791	            const wxRect rect = m_hits[actions[m_action_focus]].rect;
 792	            gc.SetPen(wxPen(p.border_focus, FromDIP(m_theme.metrics().focus.width)));
 793	            gc.SetBrush(*wxTRANSPARENT_BRUSH);
 794	            gc.DrawRoundedRectangle(rect.x + 1, rect.y + 1, rect.width - 2, rect.height - 2, FromDIP(m_theme.metrics().radius_standard));
 795	        }
 796	    }
 797	}
