 799	void LeftPane::draw_tabs(wxGraphicsContext& gc, int width)
 800	{
 801	    const ShellPalette&    p    = m_theme.palette(m_dark);
 802	    const LeftPaneMetrics& pane = m_theme.metrics().left_pane;
 803	    const int top    = FromDIP(pane.padding_y);
 804	    const int height = FromDIP(pane.tab_height);
 805	
 806	    gc.SetPen(*wxTRANSPARENT_PEN);
 807	    gc.SetBrush(wxBrush(p.surface_canvas));
 808	    gc.DrawRectangle(0, top, width, height);
 809	
 810	    const struct { PaneTab tab; wxString label; } tabs[] = {{PaneTab::Plates, _L("Plates")}, {PaneTab::Project, _L("Project")}};
 811	    for (int index = 0; index < 2; ++index) {
 812	        const bool   active = m_navigation.tab() == tabs[index].tab;
 813	        const wxRect rect(index * width / 2, top, width / 2, height);
 814	        gc.SetFont(m_theme.font(active ? TextRole::LabelBold : TextRole::Label), active ? p.text_primary : p.text_secondary);
 815	        double tw = 0, th = 0;
 816	        gc.GetTextExtent(tabs[index].label, &tw, &th);
 817	        gc.DrawText(tabs[index].label, rect.x + (rect.width - tw) / 2, rect.y + (rect.height - th) / 2);
 818	        if (active) {
 819	            gc.SetBrush(wxBrush(p.action_primary));
 820	            gc.DrawRectangle(rect.x, rect.y + rect.height - FromDIP(pane.tab_indicator_height), rect.width,
 821	                             FromDIP(pane.tab_indicator_height));
 822	            if (HasFocus() && m_tab_focus_visible) {
 823	                gc.SetPen(wxPen(p.border_focus, FromDIP(m_theme.metrics().focus.width)));
 824	                gc.SetBrush(*wxTRANSPARENT_BRUSH);
 825	                gc.DrawRoundedRectangle(rect.x, rect.y, rect.width, rect.height,
 826	                                        FromDIP(m_theme.metrics().radius_standard));
 827	            }
 828	        }
 829	        m_hits.push_back({Hit::Kind::Tab, rect, 0, tabs[index].tab});
 830	    }
 831	}
