 833	int LeftPane::draw_plates(wxGraphicsContext& gc, int top, int width)
 834	{
 835	    const ShellPalette&    p    = m_theme.palette(m_dark);
 836	    const LeftPaneMetrics& pane = m_theme.metrics().left_pane;
 837	    int y = top + FromDIP(pane.list_padding_y);
 838	
 839	    std::size_t index = 0;
 840	    while (index < m_rows.size()) {
 841	        const PaneRow& row = m_rows[index];
 842	        // A block is a plate row with everything listed under it, or the
 843	        // off-plate group.
 844	        std::size_t end = index + 1;
 845	        while (end < m_rows.size() && m_rows[end].kind != PaneRow::Kind::Plate && m_rows[end].kind != PaneRow::Kind::OffPlateHeader)
 846	            ++end;
 847	
 848	        int block = FromDIP(pane.plate_row_height);
 849	        // A folded plate adds its summary line and the padding under it.
 850	        if (row.kind == PaneRow::Kind::Plate && !row.expanded)
 851	            block += FromDIP(m_theme.type_style(TextRole::Metadata).line_height + pane.summary_padding_bottom);
 852	        block += static_cast<int>(end - index - 1) * FromDIP(pane.object_row_height);
 853	
 854	        // The block's ground, then its rows.
 855	        gc.SetPen(*wxTRANSPARENT_PEN);
 856	        gc.SetBrush(wxBrush(p.surface_canvas));
 857	        gc.DrawRoundedRectangle(0, y, width, block, FromDIP(m_theme.metrics().radius_standard));
 858	
 859	        int row_y = y;
 860	        draw_plate_row(gc, row, index, row_y, width, block);
4210	        load_multi_plate_fixture();
4211	        check(m_plater->canvas3D()->get_volumes_count() >= 2, "stock_mode_canvas_renders_fixture");
4212	        // Exiting with loaded volumes trips an inherited teardown crash in
4213	        // ~GLCanvas3D (Selection::clear() re-enters the destroyed Plater);
4214	        // see the Phase 1 handback. End on an empty project like the shell
4215	        // scenario does.
4216	        check(m_plater->new_project(true, true) != wxID_CANCEL, "stock_mode_teardown_project");
4217	    }
