8716	
8717	            // Both checks below need a pane that is not sitting at its own
8718	            // minimum: only a pane wide enough to have width taken from it
8719	            // exercises the width policy at all.
8720	            const wxSize whole = m_frame->GetSize();
8721	            m_frame->SetSize(m_frame->FromDIP(760), whole.y);
8722	            m_frame->Layout();
8723	            wxYield();
