   215	class ShellTheme
   216	{
   217	public:
   218	    // Loads both semantic palettes, the metrics and the text roles from the
   219	    // packaged token file. Throws std::runtime_error when the file is missing
   220	    // or malformed so the caller can fall back to the standard Orca
   221	    // presentation. Needs no wx initialisation.
   222	    static ShellTheme load_from_resources();
   223	
   224	    const ShellPalette& palette(bool dark) const { return dark ? m_dark : m_light; }
   225	    const ShellMetrics& metrics() const { return m_metrics; }
   226	    const TypeStyle&    type_style(TextRole role) const { return m_type_styles[size_t(role)]; }
   227	
   228	    // The wxFont for a role, built once on first use through OrcaSlicer's
   229	    // Label::sysFont so it carries the same face as the rest of the
   230	    // application, then sized so the role's DIP size is its em on every
   231	    // platform (sysFont's own point scaling rounds the token off on Windows
   232	    // and Linux). Requires wx to be initialised.
   233	    const wxFont& font(TextRole role) const;
   234	
   235	private:
   236	    ShellPalette m_light;
   237	    ShellPalette m_dark;
   238	    ShellMetrics m_metrics;
   239	    std::array<TypeStyle, kTextRoleCount> m_type_styles{};
   240	    mutable std::array<wxFont, kTextRoleCount> m_fonts{};
   241	};
