354	{
355	    const auto& p = m_theme.palette(m_dark);
356	    const bool primary = m_style == HeaderStyle::PrimaryLeft || m_style == HeaderStyle::PrimaryRight;
357	    const bool chip    = m_style == HeaderStyle::ChipLeft || m_style == HeaderStyle::ChipRight;
