383	        // the shared inner edge so only its own outer corners round. The top
384	        // and bottom borders then meet exactly across the seam.
385	        gc->SetPen(wxPen(p.border_subtle));
386	        gc->SetBrush(wxBrush(fill));
387	        gc->DrawRoundedRectangle(m_style == HeaderStyle::ChipLeft ? 0.5 : 0.5 - r, 0.5, w - 1 + r, h - 1, r);
388	        if (m_style == HeaderStyle::ChipRight) {
389	            gc->SetPen(wxPen(p.border_subtle));
390	            gc->StrokeLine(0.5, 0.5, 0.5, h - 0.5);
391	        }
392	    } else {
