394	        gc->SetBrush(wxBrush(fill));
395	        gc->DrawRoundedRectangle(0.5,0.5,w-1,h-1,r);
396	    }
397	    if (primary && (m_style == HeaderStyle::PrimaryRight || m_attached)) {
398	        gc->SetPen(*wxTRANSPARENT_PEN);
