400	    }
401	    if (m_style == HeaderStyle::PrimaryRight) {
402	        gc->SetPen(wxPen(p.action_primary_hover));
403	        gc->StrokeLine(0,FromDIP(7),0,h-FromDIP(7));
404	    }
405	
406	    const double icon_size = FromDIP(m.button.icon.icon_size);
407	    const HeaderIcon icon = m_open && m_icon == HeaderIcon::Down ? HeaderIcon::Up : m_icon;
408	    if (m_style == HeaderStyle::PrimaryRight || m_style == HeaderStyle::Outline) {
