420	        x += FromDIP(24);
421	    }
422	    if (const int lead = lead_width(); lead > 0) {
423	        // A slot's number, ahead of its dot, in the label's own face.
424	        gc->SetFont(GetFont(), foreground);
425	        double tw, th; gc->GetTextExtent(m_decoration.lead, &tw, &th);
426	        gc->DrawText(m_decoration.lead, x, (h-th)/2);
427	        x += lead;
428	    }
429	    if (m_decoration.dot.has_value()) {
430	        const double dot = FromDIP(8);
431	        draw_dot(*gc, m_decoration.dot, x, (h-dot)/2, dot, p);
432	        x += FromDIP(16);
433	    }
434	    if (const int run = slot_dots_width(); run > 0) {
435	        const SlotDotMetrics& metrics = m_theme.metrics().slot_dot;
436	        const bool   shrink = m_decoration.small_slot_dots;
437	        const double dot   = FromDIP(shrink ? metrics.compact_size : metrics.size);
438	        const double gap   = FromDIP(shrink ? metrics.compact_gap : metrics.gap);
439	        double       at    = x;
