472	        gc->DrawText(m_row_action_label, rect.x + (rect.width - tw) / 2, rect.y + (rect.height - th) / 2);
473	        right -= rect.width + FromDIP(m.space_2);
474	    } else if (m_row_action != HeaderIcon::None) {
475	        // Revealed on hover or keyboard selection; the slot is always
476	        // reserved, so rows do not shift when the pointer crosses them.
477	        if (highlighted) {
