365	                            m_style == HeaderStyle::Quiet ? p.text_secondary : p.text_primary;
366	    const bool highlighted = (m_hover || m_open || m_menu_selected) && IsEnabled();
367	    wxColour fill = primary ? (!IsEnabled() ? p.action_disabled : m_pressed || m_open ? p.action_primary_pressed :
368	                              m_hover ? p.action_primary_hover : p.action_primary) :
369	                   highlighted ? p.surface_selected :
370	                   // The filament half sits on a quieter ground than the printer
371	                   // half, so the chip reads as two things inside one outline.
372	                   m_style == HeaderStyle::ChipRight ? p.surface_subtle :
373	                   m_style == HeaderStyle::Menu ? p.surface_raised : p.surface_canvas;
374	
375	    const ShellMetrics& m = m_theme.metrics();
376	    const double w = client.x, h = client.y;
377	    const double r = FromDIP(primary ? m.radius_compact :
378	                             chip ? m.chip.radius :
379	                             m_style == HeaderStyle::Menu ? m.menu_row.radius :
