480	                      icon_size, p.text_secondary);
481	        }
482	        right -= FromDIP(20);
483	    }
484	    if (m_decoration.trailing != HeaderIcon::None) {
485	        draw_icon(*gc, m_decoration.trailing, right-icon_size, (h-icon_size)/2, icon_size, p.text_secondary);
486	        right -= FromDIP(20);
487	    }
488	    if (m_decoration.check) {
489	        draw_icon(*gc, HeaderIcon::Check, right-icon_size, (h-icon_size)/2, icon_size, p.action_primary);
490	        right -= FromDIP(20);
491	    }
492	    if (!m_decoration.detail.empty() && !m_decoration.detail_inline) {
493	        gc->SetFont(detail_font(), p.text_secondary);
494	        double tw,th; gc->GetTextExtent(m_decoration.detail,&tw,&th);
495	        gc->DrawText(m_decoration.detail, right-tw, (h-th)/2);
496	        right -= tw + FromDIP(16);
497	    }
498	    if (m_decoration.status != StatusTone::None) {
499	        if (!m_decoration.status_word.empty()) {
