338	// Painting is separated from the paint event so the same code can draw into an
339	// offscreen bitmap. Appearance is then verifiable from inside the running
340	// application, without a screen capture -- which also makes the light and dark
341	// pair reproducible rather than a photograph of one machine's screen.
342	wxBitmap HeaderButton::snapshot()
343	{
344	    const wxSize size = GetClientSize().x > 0 ? GetClientSize() : GetBestSize();
345	    wxBitmap bitmap(size);
346	    wxMemoryDC dc(bitmap);
347	    std::unique_ptr<wxGraphicsContext> gc(wxGraphicsContext::Create(dc));
348	    if (gc) draw(dc, *gc, size);
349	    dc.SelectObject(wxNullBitmap);
350	    return bitmap;
