 32	    m_printer->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { if (m_printer_activated) m_printer_activated(); });
 33	    m_filament->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { if (m_filament_activated) m_filament_activated(); });
 34	
 35	    // Left and right move between the halves; the halves themselves keep
 36	    // Return and Space, which HeaderButton already handles.
 37	    auto arrows = [](HeaderButton* self, HeaderButton* other) {
 38	        self->Bind(wxEVT_KEY_DOWN, [self, other](wxKeyEvent& event) {
 39	            const int key = event.GetKeyCode();
 40	            if (key == WXK_LEFT || key == WXK_RIGHT) {
 41	                if (self != other) other->SetFocus();
 42	                return;
 43	            }
 44	            event.Skip();
 45	        });
 46	    };
 47	    arrows(m_printer, m_filament);
 48	    arrows(m_filament, m_printer);
 49	
 50	    Bind(wxEVT_SIZE, [this](wxSizeEvent& event) { layout(); event.Skip(); });
 51	}
 52	
 53	void PrinterFilamentChip::set_printer(const wxString& nickname, const wxString& nozzle, const wxString& tooltip)
 54	{
 55	    const wxString name = nickname.empty() ? _L("Select printer") : nickname;
 56	    m_printer->SetLabel(name);
 57	    HeaderRowDecoration decoration;
 58	    // "X1 Carbon · 0.4" reads as one line.
 59	    decoration.detail        = nozzle;
 60	    decoration.detail_inline = true;
 61	    decoration.trailing      = HeaderIcon::Caret;
 62	    m_printer->set_decoration(std::move(decoration));
 63	    // The tooltip carries the full text the chip may have ellipsized. It says
 64	    // what is selected and nothing about whether it is loaded: the chip makes
 65	    // no claim about the physical machine.
 66	    m_printer->SetToolTip(tooltip.empty() ? name : tooltip);
 67	    InvalidateBestSize();
 68	    layout();
 69	}
 70	
 71	void PrinterFilamentChip::set_filaments(const FilamentChipModel& model, const wxString& label, const wxString& tooltip)
 72	{
 73	    m_filament->SetLabel(label.empty() ? _L("Select filament") : label);
 74	    HeaderRowDecoration decoration;
 75	    for (const ChipDot& dot : model.dots)
 76	        decoration.slot_dots.push_back({wxColour(wxString::FromUTF8(dot.colour)), dot.faded});
 77	    if (model.folded > 0)
 78	        decoration.slot_more = wxString::Format("+%d", int(model.folded));
 79	    decoration.small_slot_dots = model.shrunk;
 80	    decoration.trailing        = HeaderIcon::Caret;
 81	    m_filament->set_decoration(std::move(decoration));
 82	    m_filament->SetToolTip(tooltip.empty() ? label : tooltip);
 83	    InvalidateBestSize();
 84	    layout();
 85	}
 86	
 87	void PrinterFilamentChip::set_dark(bool dark)
 88	{
 89	    m_printer->set_dark(dark);
 90	    m_filament->set_dark(dark);
 91	    Refresh();
 92	}
 93	
 94	wxSize PrinterFilamentChip::DoGetBestSize() const
 95	{
 96	    const wxSize left = m_printer->GetBestSize(), right = m_filament->GetBestSize();
 97	    return {left.x + right.x, std::max(left.y, right.y)};
 98	}
 99	
100	wxBitmap PrinterFilamentChip::snapshot()
101	{
102	    const wxBitmap left = m_printer->snapshot(), right = m_filament->snapshot();
103	    wxBitmap combined(left.GetWidth() + right.GetWidth(), std::max(left.GetHeight(), right.GetHeight()));
104	    wxMemoryDC dc(combined);
105	    dc.DrawBitmap(left, 0, 0);
106	    dc.DrawBitmap(right, left.GetWidth(), 0);
107	    dc.SelectObject(wxNullBitmap);
108	    return combined;
109	}
110	
111	void PrinterFilamentChip::layout()
112	{
113	    const wxSize size = GetClientSize();
114	    if (size.x <= 0) return;
115	    // Under pressure both halves give up width in proportion to what they
116	    // asked for, so neither collapses to its ellipsis while the other keeps
117	    // slack.
118	    const int wanted_left  = m_printer->GetBestSize().x;
119	    const int wanted_right = m_filament->GetBestSize().x;
120	    const int wanted       = wanted_left + wanted_right;
121	    const int left = wanted <= size.x || wanted == 0 ? wanted_left : size.x * wanted_left / wanted;
122	    m_printer->SetSize(0, 0, left, size.y);
123	    m_filament->SetSize(left, 0, size.x - left, size.y);
124	}
