   270	void StatusRow::layout_header()
   271	{
   272	    const int margin = FromDIP(16), gap = FromDIP(8), height = GetClientSize().y;
   273	    auto place = [height](HeaderButton* button, int x, int width = -1) {
   274	        wxSize size = button->GetBestSize();
   275	        if (width >= 0) size.x = width;
   276	        button->SetSize(x,(height-size.y)/2,size.x,size.y);
   277	    };
   278	    int right = GetClientSize().x-margin-m_overflow_button->GetBestSize().x;
   279	    place(m_overflow_button,right);
   280	    right -= gap;
   281	    if (m_agent_toggle->IsShown()) {
   282	        right -= m_agent_toggle->GetBestSize().x;
   283	        place(m_agent_toggle,right);
   284	        right -= gap;
   285	    }
   286	    if (m_menu_button->IsShown()) {
   287	        right -= m_menu_button->GetBestSize().x;
   288	        place(m_menu_button,right);
   289	    }
   290	    right -= m_slice_button->GetBestSize().x;
   291	    place(m_slice_button,right);
   292	    place(m_home_button,margin);
   293	    const int left = margin+m_home_button->GetBestSize().x+gap;
   294	    const int available = std::max(0,right-gap-left);
   295	    const int width = std::min(m_chip->GetBestSize().x,available);
   296	    const wxSize chip = m_chip->GetBestSize();
   297	    m_chip->SetSize(left+(available-width)/2,(height-chip.y)/2,width,chip.y);
   298	}
