+class AgentPaneHeader final : public wxPanel
+{
+public:
+    AgentPaneHeader(wxWindow* parent, const ShellTheme& theme, int height, std::function<void()> toggle)
+        : wxPanel(parent, wxID_ANY)
+        , m_theme(theme)
+        , m_toggle(std::move(toggle))
+    {
+        SetName("Agent pane header");
+        SetMinSize(wxSize(-1, height));
+        SetBackgroundStyle(wxBG_STYLE_PAINT);
+
+        m_button = new HeaderButton(this, theme, HeaderStyle::Outline, wxEmptyString, HeaderIcon::PanelOpen);
+        m_button->SetName("Agent panel close");
+        m_button->SetToolTip(_L("Hide the Agent panel"));
+        m_button->Bind(wxEVT_BUTTON, [this](wxCommandEvent&) { if (m_toggle) m_toggle(); });
+
+        Bind(wxEVT_SIZE, [this](wxSizeEvent& event) { layout(); event.Skip(); });
+        Bind(wxEVT_PAINT, [this](wxPaintEvent&) {
+            wxAutoBufferedPaintDC dc(this);
+            const ShellPalette& palette = m_theme.palette(m_dark);
+            dc.SetBackground(wxBrush(palette.surface_canvas));
+            dc.Clear();
+            dc.SetPen(wxPen(palette.border_subtle));
+            dc.DrawLine(0, GetClientSize().y - 1, GetClientSize().x, GetClientSize().y - 1);
+        });
+    }
+
+    void apply_appearance(bool dark)
+    {
+        m_dark = dark;
+        const ShellPalette& palette = m_theme.palette(dark);
+        SetBackgroundColour(palette.surface_canvas);
+        m_button->set_dark(dark);
+        Refresh();
+    }
+
+private:
+    void layout()
+    {
+        const wxSize size = m_button->GetBestSize();
+        m_button->SetSize(GetClientSize().x - FromDIP(16) - size.x,
+                          (GetClientSize().y - size.y) / 2, size.x, size.y);
+    }
+
+    const ShellTheme&    m_theme;
+    std::function<void()> m_toggle;
+    HeaderButton*         m_button{nullptr};
+    bool                  m_dark{false};
+};
