      <p className="footnote">Registered JusPrin account, your own key, or an AI tool you already use.</p>
    </div>
  );
  if (fileReports.length === 0) return offer;
  return (
    <div className="agent-offer-with-notes">
      {fileReports.map(({ id, report }) => <FileNotesCard key={id} report={report} />)}
      {offer}
    </div>
  );
}

/* File notes sit above the original setup offer when they are the only
   conversation items. The combined surface scrolls in a short dock. */
.agent-offer-with-notes {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 16px;
  overflow-y: auto;
  background: var(--surface-canvas);
}

.agent-offer-with-notes .pane-state {
  flex: none;
  justify-content: flex-start;
  padding: 0;
}

/* Dock header shown in place of the conversation chrome while no Agent
   service is configured; same row metrics as .chat-header. */
.agent-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--surface-canvas);
}

.agent-header .agent-title {
  flex: 1;
  font: var(--font-body-bold);
}

.agent-header .agent-badge {
  flex: 0 0 auto;
  padding: 0 8px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-pill);
  color: var(--text-secondary);
  font: var(--font-metadata);
  letter-spacing: 0.04em;
}

/* Agent setup. The screens replace the dock body in place, so they reuse
   .pane-state's metrics and only add the card, the provider tabs, and the
   key row. */
/* The setup screens are the only pane states taller than the dock: a diff, a
   command and an error banner can all be on screen at once. They scroll, so
   the actions at the bottom stay reachable in a short window. */
.pane-state.setup {
  justify-content: flex-start;
  align-self: stretch;
  min-height: 0;
    const session = state.session;
    const printerAction = (action: string) => client.send('printer_action', { action });
    // No tool closes the panel for the model: the person decides when they
    // are done, with Back or by opening the printer's own settings.
    const back = () => {
      const started = state.messages.some((message) => message.role === 'user') ||
        state.attachments.some((attachment) => attachment.state === 'staged') || printerDraft.current.trim() !== '';
      if (started) setConfirmPrinterClose(true);
      else printerAction('close');
    };
    return (
      // The whole panel takes a photo, not only the composer: a picture of
      // the printer is dropped where the person is looking.
      <div
        className="app app--printer app--printer-setup"
        onDragOver={(event) => event.preventDefault()}
        onDrop={(event) => {
          const files = Array.from(event.dataTransfer.files ?? []);
          if (files.length === 0) return;
          event.preventDefault();
          attachFiles(files, 'drop');
        }}
      >
        {errorNotice}
        <div className="chat-content">
          <header className="chat-header printer-header">
            <button type="button" className="printer-link-button" onClick={back}>
              ‹ Back
            </button>
            <button type="button" className="printer-link-button" onClick={() => printerAction(session?.printerName ? 'open_printer_settings' : 'manual_setup')}>
              {session?.printerName ? 'Open printer settings' : 'Browse the full printer list'}
            </button>
          </header>
          {confirmPrinterClose && (
            <Dialog title="Close this conversation?" onClose={() => setConfirmPrinterClose(false)}>
              <p>This conversation will be closed. You can't continue it at a later point. Are you sure?</p>
              <div className="chat-dialog-buttons">
                <button type="button" onClick={() => setConfirmPrinterClose(false)}>Cancel</button>
                <button type="button" className="danger" onClick={() => { setConfirmPrinterClose(false); printerAction('close'); }}>
                  Close conversation
                </button>
              </div>
            </Dialog>
          )}
          {notConfigured ? (
            body()
          ) : (
            <MessageList
              messages={state.messages}
              attachments={state.attachments}
              streamingMessageId={state.streamingMessageId}
              onSend={sendMessage}
              // The person decides on the credential's card and on a settings
              // change's; every other tool is what the model then says it did.
              toolActivities={state.toolActivities.filter((activity) =>
                activity.tool === 'printer_connect' || activity.tool === 'settings_apply_patch')}
}

let clientAttachmentCounter = 0;
function nextClientAttachmentId(): string {
  clientAttachmentCounter += 1;
  return `ca-${clientAttachmentCounter}-${Math.random().toString(36).slice(2, 10)}`;
}

function readAsDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(typeof reader.result === 'string' ? reader.result : '');
    reader.onerror = () => reject(reader.error ?? new Error('read failed'));
    reader.readAsDataURL(file);
  });
}

