  flex: 0 0 auto;
  padding: 12px;
  background: var(--surface-canvas);
}

.current-setup {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 12px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-container);
  background: var(--surface-subtle);
