/* Every color, radius, and type metric below resolves through a custom
   property that tokens.ts writes from resources/jusprin/ui/design-tokens.json:
   --<group>-<name> for colors, --radius-<name> for radii, --font-<role> for
   the `font` shorthand of each type role and --font-code for code. Padding,
   margin, and gap stay literal but must sit on the spacing scale. styles.test.ts
   fails the build on any literal outside those rules. */

/* The product font ships with OrcaSlicer, but it is registered as a private
   font of the native process and WKWebView renders in a separate process
   that cannot see it. A Latin subset is embedded so the Agent page uses the
   same face as the native shell; CJK text falls through to the system font. */
@font-face {
  font-family: 'HarmonyOS Sans SC';
  font-weight: 400;
  font-style: normal;
  src: url('../../WebShared/fonts/HarmonyOS_Sans_SC_Regular_latin.woff') format('woff');
}
@font-face {
  font-family: 'HarmonyOS Sans SC';
  font-weight: 700;
  font-style: normal;
  src: url('../../WebShared/fonts/HarmonyOS_Sans_SC_Bold_latin.woff') format('woff');
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  font: var(--font-body);
  color: var(--text-primary);
  background: var(--surface-subtle);
  -webkit-user-select: text;
  user-select: text;
}

.app {
  position: relative;
  min-width: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  height: 100%;
}

:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

/* Compact workspace context header */
.context-summary {
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--surface-canvas);
  font: var(--font-label);
  color: var(--text-secondary);
}

.context-summary .project {
  color: var(--text-primary);
  font: var(--font-label-bold);
}

/* Current setup card. Measured from the Figma "Current Setup Card" page:
   a 405px card inset 12px inside a 429px dock, tinted surface/subtle with a
   2px action/primary edge, container radius, 16/12 padding and a 4px row gap.
   The compact rows keep settings and print facts readable; expansion grows the same
   card rather than floating a second panel under it. */
.pinned-setup {
  flex: 0 0 auto;
  padding: 12px;
  background: var(--surface-canvas);
}

.current-setup {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 12px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-container);
  background: var(--surface-subtle);
