    void after_agent()
    {
        verify_resize();
        verify_project_replacement();
        verify_uninstall_restores_stock([self = shared_from_this()] { self->finish(); });
    }

    void verify_resize()
    {
        auto* divider = wxWindow::FindWindowByName("Resize Agent panel", m_frame);
        auto* pane = installed_shell()->agent_pane();
        check(divider != nullptr && divider->IsShown(), "agent_resize_handle_shown");
        check(divider != nullptr && divider->GetSize().x == divider->FromDIP(8),
              "agent_resize_handle_matches_token_width");
        if (divider != nullptr) {
            auto drag = [divider](int delta_x) {
                const wxPoint start(divider->GetClientSize().x / 2, divider->GetClientSize().y / 2);
                wxMouseEvent down(wxEVT_LEFT_DOWN);
                down.SetPosition(start);
                down.SetEventObject(divider);
                divider->GetEventHandler()->ProcessEvent(down);
                wxMouseEvent motion(wxEVT_MOTION);
                motion.SetPosition(start + wxPoint(delta_x, 0));
                motion.SetEventObject(divider);
                divider->GetEventHandler()->ProcessEvent(motion);
                wxMouseEvent up(wxEVT_LEFT_UP);
                up.SetPosition(start + wxPoint(delta_x, 0));
                up.SetEventObject(divider);
                divider->GetEventHandler()->ProcessEvent(up);
                wxYield();
            };

            auto double_click = [divider] {
                const wxPoint start(divider->GetClientSize().x / 2, divider->GetClientSize().y / 2);
                for (wxEventType type : {wxEVT_LEFT_DOWN, wxEVT_LEFT_UP, wxEVT_LEFT_DCLICK, wxEVT_LEFT_UP}) {
                    wxMouseEvent event(type);
                    event.SetPosition(start);
                    event.SetEventObject(divider);
                    divider->GetEventHandler()->ProcessEvent(event);
                }
                wxYield();
            };
            auto* project_toggle = dynamic_cast<HeaderButton*>(
                wxWindow::FindWindowByName("Agent panel", installed_shell()->status_row()));
            auto press_toggle = [project_toggle, pane] {
                if (!installed_shell()->is_agent_pane_collapsed()) {
                    static int next = 0;
                    pane->web_view().host().on_page_message(
                        nlohmann::json{{"protocol", Agent::Protocol::kName},
                                       {"version", Agent::Protocol::kVersion},
                                       {"id", "pane-toggle-" + std::to_string(++next)},
                                       {"type", Agent::Protocol::kShellAction},
                                       {"payload", {{"action", "collapse_agent_pane"}}}}
                            .dump());
                    wxYield();
                    return;
                }
                if (project_toggle == nullptr) return;
                wxMouseEvent press(wxEVT_LEFT_DOWN), release(wxEVT_LEFT_UP);
                project_toggle->ProcessWindowEvent(press);
                project_toggle->ProcessWindowEvent(release);
                wxYield();
            };
            auto workspace_width = [this] {
                return m_plater->canvas3D()->get_wxglcanvas()->GetSize().GetWidth();
            };

            const int original_pane_width = pane->GetSize().x;
            drag(-divider->FromDIP(120));
            check(pane->GetSize().x > original_pane_width, "agent_panel_mouse_drag_grows_width");

            // However far a drag is pushed, it only sizes the pane: it stops
            // at the minimum and never closes it, so aiming for a narrow pane
            // cannot take the conversation off the screen by accident.
            drag(divider->FromDIP(2000));
            check(pane->GetSize().x == pane->FromDIP(320), "agent_panel_drag_stops_at_minimum_width");
            check(!installed_shell()->is_agent_pane_collapsed() && pane->IsShown() && divider->IsShown(),
                  "agent_panel_drag_never_closes_the_pane");

            drag(-divider->FromDIP(2000));
            const LeftPane* left_pane = installed_shell()->left_pane();
            const int left_width = left_pane != nullptr && left_pane->IsShown() ? left_pane->GetSize().x : 0;
            const int expected_max = std::max(pane->FromDIP(320),
                m_frame->GetClientSize().x - pane->FromDIP(320) - divider->GetSize().x - left_width);
            check(pane->GetSize().x == expected_max, "agent_panel_drag_uses_available_window_width");
            check(workspace_width() > 200, "agent_panel_drag_preserves_workspace_width");

            drag(pane->GetSize().x - original_pane_width);
            check(pane->GetSize().x == original_pane_width, "agent_panel_width_can_be_restored");

            check(project_toggle != nullptr && !project_toggle->IsShown(),
                  "agent_panel_open_toggle_leaves_project_header");
            const int open_workspace_width = workspace_width();

            double_click();
            check(installed_shell()->is_agent_pane_collapsed(), "agent_panel_divider_double_click_collapses");
            check(!pane->IsShown() && !divider->IsShown(), "agent_panel_collapse_hides_pane_and_divider");
            check(project_toggle != nullptr && project_toggle->IsShown(),
                  "agent_panel_closed_toggle_moves_to_project_header");
            check(workspace_width() > open_workspace_width, "agent_panel_collapse_widens_workspace");
            check(pane->web_view().host().mcp() != nullptr, "agent_panel_collapse_keeps_the_runtime");

            press_toggle();
            check(!installed_shell()->is_agent_pane_collapsed() && pane->IsShown() && divider->IsShown(),
                  "agent_panel_toggle_reopens_the_pane");
            check(pane->GetSize().x == pane->FromDIP(320), "agent_panel_reopens_at_a_usable_width");

            press_toggle();
            check(installed_shell()->is_agent_pane_collapsed(), "agent_panel_toggle_closes_the_pane");
            press_toggle();
            check(!installed_shell()->is_agent_pane_collapsed(), "agent_panel_toggle_reopens_again");

            drag(-divider->FromDIP(120));
            check(pane->GetSize().x > original_pane_width, "agent_panel_still_resizable_after_collapse");
            drag(pane->GetSize().x - original_pane_width);
            check(pane->GetSize().x == original_pane_width, "agent_panel_width_restored_after_collapse");

            // Both checks below need a pane that is not sitting at its own
            // minimum: only a pane wide enough to have width taken from it
            // exercises the width policy at all.
            const wxSize whole = m_frame->GetSize();
            m_frame->SetSize(m_frame->FromDIP(760), whole.y);
            m_frame->Layout();
            wxYield();

            // A drag that runs past the edge of a narrow window asks for a
            // width the pane cannot have. That width must not be banked: the
            // pane would take it, at the workspace's expense, as soon as the
            // window grew enough to allow it.
            drag(-divider->FromDIP(3000));
            const int narrow_max = pane->GetSize().x;
            m_frame->SetSize(m_frame->FromDIP(1400), whole.y);
            m_frame->Layout();
            wxYield();
            check(pane->GetSize().x == narrow_max,
                  "agent_panel_over_drag_is_not_banked_for_a_larger_window");

            // Shrinking the window while the pane is wider than the room left
            // for it re-runs the width policy on every step. No Layout() call
            // in the loop, on purpose: the point is what the frame's own size
            // handlers leave behind, and an extra layout against the settled
            // client size would repair a stale one before it could be seen.
            drag(-divider->FromDIP(3000));
            for (int width : {1200, 1000, 860, 760}) {
                m_frame->SetSize(m_frame->FromDIP(width), whole.y);
                wxYield();
                verify_agent_pane_tiling("shrinking_to_" + std::to_string(width) + "_dip");
            }
            for (int width : {860, 1100, 1400}) {
                m_frame->SetSize(m_frame->FromDIP(width), whole.y);
                wxYield();
                verify_agent_pane_tiling("growing_to_" + std::to_string(width) + "_dip");
            }
            m_frame->SetSize(whole);
            m_frame->Layout();
            wxYield();
            drag(pane->GetSize().x - original_pane_width);
        }

        const wxSize original = m_frame->GetSize();
        verify_agent_pane_tiling("before_resize");
        m_frame->SetSize(original + wxSize(120, 80));
        m_frame->Layout();
        StatusRow* row = installed_shell()->status_row();
        check(row->IsShown() && row->GetSize().GetWidth() > 0, "status_row_survives_resize");
        check(m_plater->canvas3D()->get_wxglcanvas()->GetSize().GetWidth() > 200, "canvas_survives_resize");
        verify_agent_pane_tiling("after_grow");
        verify_header_layout();
        m_frame->SetSize(m_frame->FromDIP(900),original.y);
        m_frame->Layout();
        // The single setup chip became a two-half printer/filament chip; both
        // halves must exist, since each anchors its own menu.
        auto* setup = wxWindow::FindWindowByName("Printer",row) && wxWindow::FindWindowByName("Filament",row)
                          ? wxWindow::FindWindowByName("Printer and filament",row) : nullptr;
        setup->SetLabel(wxString('W',180));
        row->SendSizeEvent();
        verify_header_layout();
        row->refresh();
        m_frame->SetSize(original);
        m_frame->Layout();
    }

    // Workspace, divider and pane must tile the frame's client width exactly.
    // Each one on its own can look right while the three together do not: a
    // layout run against a stale width sizes some of them for the previous
    // width, so they overlap and the pane covers part of the workspace.
    void verify_agent_pane_tiling(const std::string& name)
    {
        auto* pane = installed_shell()->agent_pane();
        auto* divider = wxWindow::FindWindowByName("Resize Agent panel", m_frame);
        if (pane == nullptr || divider == nullptr || installed_shell()->is_agent_pane_collapsed())
            return;
        const int client = m_frame->GetClientSize().x;
        const wxRect workspace = m_notebook->GetRect();
        const wxRect bar = divider->GetRect();
        const wxRect agent = pane->GetRect();
        auto* row = installed_shell()->status_row();
        auto* webview = pane->web_view().webview();
        // The Plates / Project pane, when shown, is the first column.
        const LeftPane* left_pane = installed_shell()->left_pane();
        const bool left_shown = left_pane != nullptr && left_pane->IsShown();
        const int  origin = left_shown ? left_pane->GetRect().GetRight() + 1 : 0;
        const bool tiled = (!left_shown || left_pane->GetRect().x == 0) && workspace.x == origin && workspace.GetWidth() > 0 &&
                           workspace.GetRight() + 1 == bar.x &&
                           bar.GetRight() + 1 == agent.x &&
                           agent.GetRight() + 1 == client;
        check(tiled, "agent_panel_columns_tile_the_client_" + name);
        const bool header_split = row != nullptr && webview != nullptr &&
                                  row->GetRect().x == 0 && row->GetRect().GetRight() + 1 == bar.x &&
                                  row->GetRect().y == bar.y && agent.y == bar.y &&
                                  webview->GetRect().x == 0 && webview->GetRect().y == 0 &&
                                  webview->GetRect().GetWidth() == agent.GetWidth();
        check(header_split, "agent_panel_web_header_splits_at_divider_" + name);
        if (!tiled)
            std::cerr << "HARNESS DETAIL client=" << client << " workspace=" << workspace.x << "+"
                      << workspace.GetWidth() << " divider=" << bar.x << "+" << bar.GetWidth()
                      << " pane=" << agent.x << "+" << agent.GetWidth() << '\n';
    }

    void verify_header_layout()
    {
        auto* row = installed_shell()->status_row();
        auto* home = wxWindow::FindWindowByName("Home navigation",row);
        // The single setup chip became a two-half printer/filament chip; both
        // halves must exist, since each anchors its own menu.
        auto* setup = wxWindow::FindWindowByName("Printer",row) && wxWindow::FindWindowByName("Filament",row)
                          ? wxWindow::FindWindowByName("Printer and filament",row) : nullptr;
        auto* action = wxWindow::FindWindowByName("Next print action",row);
        auto* arrow = wxWindow::FindWindowByName("Print actions",row);
        auto* more = wxWindow::FindWindowByName("Project actions",row);
        auto* toggle = wxWindow::FindWindowByName("Agent panel",row);
        check(home && setup && action && arrow && more,"header_has_all_five_controls");
        if (!home || !setup || !action || !arrow || !more) return;
        check(row->GetSize().y == row->FromDIP(56),"header_matches_56_dip_design");
        check(home->GetPosition().x == row->FromDIP(16),"header_home_left_margin");
        check(home->GetRect().GetRight() < setup->GetPosition().x && setup->GetRect().GetRight() < action->GetPosition().x,
              "header_home_setup_actions_order_without_overlap");
        // The reducer returns no menu items for a single unsliced plate, and the
        // chevron half is hidden in that state, so the joined-halves geometry
        // only applies while both halves are laid out.
        if (arrow->IsShown()) {
            check(action->GetPosition().x+action->GetSize().x == arrow->GetPosition().x,"header_split_halves_joined");
            check(arrow->GetSize().y == action->GetSize().y,"header_split_halves_equal_height");

item.aggregated_output:
{
    const PresetBundle* bundle = wxGetApp().preset_bundle;
    if (bundle == nullptr)
        return false;
    const PresetCollection& presets = type == Preset::TYPE_FILAMENT ? static_cast<const PresetCollection&>(bundle->filaments) :
                                                                      static_cast<const PresetCollection&>(bundle->printers);
    const Preset* preset = presets.find_preset(name, false);
    return preset != nullptr && preset->name == name && preset->is_visible && !preset->is_default;
}

class AgentPaneResizeHandle final : public wxPanel
{
public:
    // What the divider needs from the shell: the pane's width now, a new
    // width while dragging, and the double click that closes the pane.
    struct Callbacks
    {
        std::function<int()>     width;
        std::function<void(int)> set_width;
        std::function<void()>    toggle;
    };

    AgentPaneResizeHandle(wxWindow* parent, const ShellTheme& theme, Callbacks callbacks)
        : wxPanel(parent, wxID_ANY, wxDefaultPosition,
                  parent->FromDIP(wxSize(theme.metrics().agent_pane.resize_handle_width, -1)),
                  wxBORDER_NONE)
        , m_theme(theme)
        , m_callbacks(std::move(callbacks))
    {
        SetName(_L("Resize Agent panel"));
        SetToolTip(_L("Drag to resize the Agent panel"));
        SetMinSize(parent->FromDIP(wxSize(m_theme.metrics().agent_pane.resize_handle_width, -1)));
        SetCursor(wxCursor(wxCURSOR_SIZEWE));
        SetBackgroundStyle(wxBG_STYLE_PAINT);

        Bind(wxEVT_PAINT, &AgentPaneResizeHandle::on_paint, this);
        Bind(wxEVT_ENTER_WINDOW, [this](wxMouseEvent&) { m_hovered = true; Refresh(); });
        Bind(wxEVT_LEAVE_WINDOW, [this](wxMouseEvent&) { m_hovered = false; Refresh(); });
        Bind(wxEVT_LEFT_DOWN, &AgentPaneResizeHandle::on_left_down, this);
        Bind(wxEVT_LEFT_UP, &AgentPaneResizeHandle::on_left_up, this);
        Bind(wxEVT_LEFT_DCLICK, &AgentPaneResizeHandle::on_double_click, this);
        Bind(wxEVT_MOTION, &AgentPaneResizeHandle::on_motion, this);
        Bind(wxEVT_MOUSE_CAPTURE_LOST, [this](wxMouseCaptureLostEvent&) { m_dragging = false; Refresh(); });
    }

private:
    void on_paint(wxPaintEvent&)
    {
        wxAutoBufferedPaintDC dc(this);
        const ShellPalette& palette = m_theme.palette(wxGetApp().dark_mode());
        dc.SetBackground(wxBrush(palette.surface_subtle));
        dc.Clear();

        const wxColour divider = m_dragging ? palette.action_primary :
                                 m_hovered  ? palette.border_strong : palette.border_subtle;
        const int line_width = FromDIP(m_theme.metrics().agent_pane.resize_handle_line_width);
        dc.SetPen(wxPen(divider, line_width));
        const int center = GetClientSize().x / 2;
        dc.DrawLine(center, 0, center, GetClientSize().y);
    }

    void on_left_down(wxMouseEvent& event)
    {
        m_drag_origin_x = ClientToScreen(event.GetPosition()).x;
        m_drag_origin_width = m_callbacks.width();
        m_dragging = true;
        CaptureMouse();
        Refresh();
    }

    void on_left_up(wxMouseEvent&)
    {
        end_drag();
    }

    void on_double_click(wxMouseEvent&)
    {
        // wx sends down/up before the double click, so a drag may be open.
        end_drag();
        m_callbacks.toggle();
    }

    void on_motion(wxMouseEvent& event)
    {
        if (!m_dragging || !HasCapture())
            return;
        const int pointer_x = ClientToScreen(event.GetPosition()).x;
        // A drag only ever sizes the pane; it stops at the minimum width and
        // never closes it. Closing is deliberate -- the header button or a
        // double click on this divider -- because a drag that closed the pane
        // on its own would take the conversation off the screen as a side
        // effect of aiming for a narrow one.
        m_callbacks.set_width(m_drag_origin_width + m_drag_origin_x - pointer_x);
    }

    void end_drag()
    {
        if (!m_dragging)
            return;
        m_dragging = false;
        if (HasCapture())
            ReleaseMouse();
        Refresh();
    }

    const ShellTheme& m_theme;
                [this] { restore_task_panel(); },
                [this](const std::string& added) { m_home->refresh(added); },
                [this] { mark_agent_config_possibly_changed(); },
                [](std::size_t slot) { SetupCommands::open_filament_settings(slot); }});
        m_home->backend().set_conversation_opener(
            [this](const std::string& printer_name, bool connect) { open_printer_conversation(printer_name, connect); });

        main_sizer.Detach(&tabpanel);
        m_center_sizer = new wxBoxSizer(wxHORIZONTAL);
        m_project_sizer = new wxBoxSizer(wxVERTICAL);
        m_project_content_sizer = new wxBoxSizer(wxHORIZONTAL);
        m_workspace_sizer = new wxBoxSizer(wxVERTICAL);
        m_workspace_sizer->Add(&tabpanel, 1, wxEXPAND);
        m_workspace_sizer->Add(m_home, 1, wxEXPAND);
        m_left_pane = new LeftPane(&frame, *m_theme, *m_workspace);
        m_left_pane->set_project_sources({m_persistence.get(), m_autosave.get(),
            [this] {
                // OrcaSlicer's project-information editor lives on its Project page.
                m_tabpanel->SetSelection(MainFrame::tpProject);
                if (auto* project = dynamic_cast<ProjectPanel*>(m_tabpanel->GetPage(MainFrame::tpProject)))
                    project->show_info_editor(true);
            }});
        m_project_content_sizer->Add(m_left_pane, 0, wxEXPAND);
        m_project_content_sizer->Add(m_workspace_sizer, 1, wxEXPAND);
        m_project_sizer->Add(m_status_row, 0, wxEXPAND);
        m_project_sizer->Add(m_project_content_sizer, 1, wxEXPAND);
        m_center_sizer->Add(m_project_sizer, 1, wxEXPAND);
        m_center_sizer->Add(m_agent_resize_handle, 0, wxEXPAND);
        m_center_sizer->Add(m_agent_pane, 0, wxEXPAND);
        m_center_sizer->Add(m_printer_panel, 1, wxEXPAND);
        m_printer_panel->Hide();
        main_sizer.Add(m_center_sizer, 1, wxEXPAND);

        tabpanel.GetBtnsListCtrl()->Hide();
        plater->set_sidebar_available(false);
        plater->set_auto_preview_after_slice(false);

        // The collapse toolbar belongs to the Plater and is shared by the
        // Prepare and Preview canvases, so this controller is its single
        // owner for the shell's lifetime.
        plater->get_collapse_toolbar().set_enabled(false);

        // Hide the whole legacy canvas-overlay layer on the Prepare canvas
        // (main toolbar, gizmo picker, plate controls, navigator, canvas menu)
        // and the per-plate corner icons; the fork's own UI owns the canvas.
        // The active gizmo stays interactive so shell controls can drive it.
        // Add-model remains available through File > Import and drag-drop.
        if (GLCanvas3D* prepare_canvas = plater->get_view3D_canvas3D()) {
            m_prepare_canvas_presentation.attach(*prepare_canvas);
        }

        // The frame may outlive a runtime detach, so use a tracked event sink
        // and disconnect it when uninstalling the controller.
        frame.Bind(wxEVT_DESTROY, &ShellController::on_frame_destroy, this);
        frame.Bind(wxEVT_SIZE, &ShellController::on_frame_size, this);

        // A member function rather than a lambda so uninstall() can take it
        // off again: the Notebook outlives this controller.
        tabpanel.Bind(wxEVT_NOTEBOOK_PAGE_CHANGED, &ShellController::on_notebook_page_changed, this);

        m_installed = true;
        on_page_changed();
        apply_current_appearance();
        m_status_row->refresh();
        frame.Layout();
        apply_agent_pane_width();
        m_persistence.reset();
        m_workspace.reset();
    }
    event.Skip();
}

void ShellController::on_frame_size(wxSizeEvent& event)
{
    event.Skip();
    if (m_installed)
        apply_agent_pane_width();
}

int ShellController::agent_pane_width_within(int width) const
{
    if (m_theme == nullptr || m_frame == nullptr)
        return width;
    const AgentPaneMetrics& metrics = m_theme->metrics().agent_pane;
    const int min_width = m_frame->FromDIP(metrics.min_width);
    const int workspace_min_width = m_frame->FromDIP(metrics.workspace_min_width);
    const int handle_width = m_frame->FromDIP(metrics.resize_handle_width);
    // The Plates / Project pane is also beside the canvas, so the Agent pane
    // may not take what the canvas needs while it is on screen.
    const int left_width = m_left_pane != nullptr && m_left_pane->IsShown() ? m_left_pane->GetSize().x : 0;
    const int max_width = std::max(min_width, m_frame->GetClientSize().x - workspace_min_width - handle_width - left_width);
    return std::clamp(width, min_width, max_width);
}

void ShellController::request_agent_pane_width(int width)
{
    // Remember what the pane can actually take, not what the pointer asked
    // for. A drag that runs past the edge of a small window would otherwise
    // record a width the pane never had, and the pane would claim it -- at the
    // workspace's expense -- the next time the window grew enough to allow it.
    // A width the window merely cannot afford right now is a different case:
    // apply_agent_pane_width() narrows the pane without touching the
    // preference, so growing the window restores the width the person chose.
    m_agent_pane_preferred_width = agent_pane_width_within(width);
    apply_agent_pane_width();
}

void ShellController::apply_agent_pane_width()
{
    if (m_theme == nullptr || m_frame == nullptr || m_center_sizer == nullptr || m_agent_pane == nullptr)
        return;
    if (m_agent_pane_collapsed)
        return;
    const int width = agent_pane_width_within(m_agent_pane_preferred_width);
    m_center_sizer->SetItemMinSize(m_agent_pane, width, -1);
    // Lay out from the frame, not from m_center_sizer. A sizer lays itself out
    // against the dimension it was last given, which during a frame resize is
    // still the previous client width; the frame reads the current one from the
    // window. Laying out the sizer directly leaves the workspace and the
    // divider sized for the old width while the pane takes the new one, so they
    // overlap, and the next resize swaps which of them is stale.
    m_frame->Layout();
}

void ShellController::set_agent_pane_collapsed(bool collapsed)
{
    if (m_agent_pane == nullptr || m_agent_resize_handle == nullptr || m_agent_pane_collapsed == collapsed)
        return;
    m_agent_pane_collapsed = collapsed;
    // Hidden, never destroyed: the conversation, the loaded page, and the MCP
    // runtime all outlive a collapse. A hidden sizer item takes no space, so
    // the workspace grows into the whole width with no second width policy.
    m_agent_pane->Show(!collapsed);
    m_agent_resize_handle->Show(!collapsed);
    if (m_status_row != nullptr)
        m_status_row->set_agent_pane_collapsed(collapsed);
    // Expanding re-applies the width policy, which lays out on its way; a
    // collapsed pane has no width to apply, so it lays out here.
    if (collapsed)
        m_frame->Layout();
    else
        apply_agent_pane_width();
}

void ShellController::open_agent_setup()
{
    m_agent_pane_user_collapsed = false;
    m_plater->set_sidebar_available(true);
    m_plater->set_auto_preview_after_slice(m_saved_auto_preview_after_slice);
    wxGetApp().show_config_wizard_on_startup = m_saved_show_config_wizard_on_startup;
    // A printer connection may have installed a provider the slicing profile
    // does not select; hand the choice back to Orca's profile-driven policy.
    wxGetApp().switch_printer_agent();
    m_tabpanel->GetBtnsListCtrl()->Show();

    if (m_center_sizer != nullptr) {
        if (m_workspace_sizer != nullptr) {
            m_workspace_sizer->Detach(m_tabpanel);
            if (m_home != nullptr)
                m_workspace_sizer->Detach(m_home);
        }
        if (m_project_content_sizer != nullptr) {
            if (m_left_pane != nullptr)
                m_project_content_sizer->Detach(m_left_pane);
            if (m_workspace_sizer != nullptr)
                m_project_content_sizer->Detach(m_workspace_sizer);
        }
        if (m_project_sizer != nullptr) {
            if (m_status_row != nullptr)
                m_project_sizer->Detach(m_status_row);
            if (m_project_content_sizer != nullptr)
                m_project_sizer->Detach(m_project_content_sizer);
        }
        if (m_project_sizer != nullptr)
            m_center_sizer->Detach(m_project_sizer);
        if (m_agent_resize_handle != nullptr)
            m_center_sizer->Detach(m_agent_resize_handle);
        if (m_agent_pane != nullptr)
            m_center_sizer->Detach(m_agent_pane);
        if (m_printer_panel != nullptr)
            m_center_sizer->Detach(m_printer_panel);
        m_main_sizer->Detach(m_center_sizer);
        delete m_workspace_sizer;
        delete m_project_content_sizer;
        delete m_project_sizer;
        delete m_center_sizer;
        m_center_sizer = nullptr;
        m_project_sizer = nullptr;
        m_project_content_sizer = nullptr;
        m_workspace_sizer = nullptr;
    }
    if (m_main_sizer->GetItem(m_tabpanel) == nullptr)
        m_main_sizer->Add(m_tabpanel, 1, wxEXPAND | wxTOP, 0);

    if (m_left_pane != nullptr) {
        m_left_pane->Destroy();
        m_left_pane = nullptr;
    }
    if (m_status_row != nullptr) {
        m_status_row->Destroy();
        m_status_row = nullptr;
    }
    if (m_agent_resize_handle != nullptr) {
        m_agent_resize_handle->Destroy();
        m_agent_resize_handle = nullptr;
    }
    if (m_agent_pane != nullptr) {
        m_agent_pane->web_view().host().tools().set_version_callbacks({}, {});
        m_agent_pane->Destroy();
        m_agent_pane = nullptr;
    }
    if (m_printer_panel != nullptr) {
        m_printer_panel->Destroy();
    }
    const bool home = m_tabpanel->GetSelection() == MainFrame::tpHome;
    if (home)
        m_home->refresh();
    m_home->set_live(home);
    // A throwaway setup webview elsewhere (the Add a printer dialog) may have
    // written a working agent config since the docked pane last checked; push
    // it in now, the same "refresh on the way in" pattern as Home's gallery
    // above, rather than reloading the page or polling continuously.
    if (m_agent_config_possibly_changed) {
        m_agent_config_possibly_changed = false;
        Agent::AgentRuntime runtime = Agent::load_agent_runtime(wxGetApp().app_config);
        m_agent_pane->web_view().host().set_agent(std::move(runtime.service), runtime.availability);
    }
    // Home and the Notebook share the workspace slot, so exactly one is shown.
    // The Notebook is only hidden while Home is the selection: post_init
    // selects the Prepare tab to map the GL canvas before it initialises
    // OpenGL, and this handler runs on that selection, so the Notebook is
    // shown at the moment the canvas has to be on screen.
    // The header belongs to the workspace: its controls act on the open
    // project, so Home, which has no project in front, shows no header.
    m_home->Show(home);
    m_tabpanel->Show(!home);
    m_status_row->Show(!home);
    // The pane lists the project being prepared; Preview draws its own plate
    // picker and Home has no project in front.
    m_left_pane->Show(!home && m_tabpanel->GetSelection() == MainFrame::tp3DEditor);
    m_frame->Layout();
    set_agent_pane_collapsed(home ? true : m_agent_pane_user_collapsed);
}

