        m_hits.push_back({Hit::Kind::AddPlate, button, 0, PaneTab::Plates});

    return y + FromDIP(pane.add_plate_padding_top + pane.add_plate_button_height + pane.add_plate_padding_bottom);
}

void LeftPane::draw_focus_ring(wxGraphicsContext& gc, std::size_t index, const wxRect& rect)
{
    if (!HasFocus() || !m_focus_visible || static_cast<int>(index) != m_focus_row)
        return;
    gc.SetPen(wxPen(m_theme.palette(m_dark).border_focus, FromDIP(m_theme.metrics().focus.width)));
    gc.SetBrush(*wxTRANSPARENT_BRUSH);
    const int inset = FromDIP(1);
    gc.DrawRoundedRectangle(rect.x + inset, rect.y + inset, rect.width - 2 * inset, rect.height - 2 * inset,
                            FromDIP(m_theme.metrics().radius_standard));
}

void LeftPane::draw_plate_row(wxGraphicsContext& gc, const PaneRow& row, std::size_t index, int& y, int width, int block_height)
{
    const ShellPalette&    p    = m_theme.palette(m_dark);
    const LeftPaneMetrics& pane = m_theme.metrics().left_pane;
    const int line   = FromDIP(pane.plate_row_height);
    const int glyph  = FromDIP(pane.glyph_size);
    const int pad_x  = FromDIP(pane.row_padding_x);
    const int gap    = FromDIP(pane.plate_gap);
    const wxRect main(0, y, width, line);
    const bool   hot = static_cast<int>(index) == m_hover_row;

    if (row.kind == PaneRow::Kind::OffPlateHeader) {
        gc.SetFont(m_theme.font(TextRole::LabelBold), p.text_primary);
        const wxString text = _L("Not on a plate") + middle_dot() + wxString::Format("%d", int(row.copies));
        double tw = 0, th = 0;
        gc.GetTextExtent(text, &tw, &th);
        gc.DrawText(fit(gc, text, width - 2 * pad_x), pad_x, y + (line - th) / 2);
        y += line;
        return;
    }

    if (hot) {
        if (!details.model.designer.empty())
            attribution = _L("by") + " " + wxString::FromUTF8(details.model.designer);
        if (!details.model.license.empty())
            attribution += (attribution.empty() ? wxString() : middle_dot()) + wxString::FromUTF8(details.model.license);
        if (!attribution.empty())
            y = draw_paragraph(gc, y, width, attribution, TextRole::Metadata, p.text_secondary);
    }
    y += FromDIP(pane.list_padding_y);

    // Project actions, in the order of the frame: prints, details, versions, export.
    const std::size_t prints = m_sources.persistence != nullptr ? m_sources.persistence->document().physical_print_count() : 0;
    if (prints > 0)
        y = draw_action_row(gc, y, width,
                            prints == 1 ? _L("Printed once") : wxString::Format(_L("Printed %d times"), int(prints)), {}, true,
                            [this] { open_project_view(ProjectView::PrintHistory); });
    y = draw_action_row(gc, y, width, _L("Details"), {}, true, [this] { open_project_view(ProjectView::Details); });
    y = draw_action_row(gc, y, width, _L("Version history"), {}, true, [this] { open_project_view(ProjectView::Versions); },
                        m_sources.autosave != nullptr);
    y = draw_action_row(gc, y, width, _L("Export project 3MF…"), {}, false, [this] { export_project(); },
                        m_sources.autosave != nullptr);
    return y;
                [this](int width) { request_left_pane_width(width); },
                [this] { toggle_left_pane(); }});
        m_left_pane->set_pane_toggle([this] { toggle_left_pane(); });
        m_status_row->set_left_pane_toggle([this] { toggle_left_pane(); });
        m_status_row->set_left_pane_collapsed(m_left_pane_collapsed);
        m_left_pane->set_project_sources({m_persistence.get(), m_autosave.get(),
            [this] {
                // OrcaSlicer's project-information editor lives on its Project page.
                m_tabpanel->SetSelection(MainFrame::tpProject);
                if (auto* project = dynamic_cast<ProjectPanel*>(m_tabpanel->GetPage(MainFrame::tpProject)))
                    project->show_info_editor(true);
            }});
        m_project_sizer->Add(m_status_row, 0, wxEXPAND);
        m_project_sizer->Add(m_workspace_sizer, 1, wxEXPAND);
        m_center_sizer->Add(m_left_pane, 0, wxEXPAND);
        m_center_sizer->Add(m_left_resize_handle, 0, wxEXPAND);
        m_center_sizer->Add(m_project_sizer, 1, wxEXPAND);
        m_center_sizer->Add(m_agent_resize_handle, 0, wxEXPAND);
        m_center_sizer->Add(m_agent_pane, 0, wxEXPAND);
        m_center_sizer->Add(m_printer_panel, 1, wxEXPAND);
        m_printer_panel->Hide();
        main_sizer.Add(m_center_sizer, 1, wxEXPAND);

        tabpanel.GetBtnsListCtrl()->Hide();
        plater->set_sidebar_available(false);
        plater->set_auto_preview_after_slice(false);

        // The collapse toolbar belongs to the Plater and is shared by the
        // Prepare and Preview canvases, so this controller is its single
        // owner for the shell's lifetime.
        plater->get_collapse_toolbar().set_enabled(false);

        // Hide the whole legacy canvas-overlay layer on the Prepare canvas
        // (main toolbar, gizmo picker, plate controls, navigator, canvas menu)
        // and the per-plate corner icons; the fork's own UI owns the canvas.
        // The active gizmo stays interactive so shell controls can drive it.

